-- Explicit stopped-copy overlay on the verified skill-purge profile; existing rows remain byte-identical.
DROP TRIGGER native_request_purge_insert_guard;
DROP TRIGGER native_request_purge_no_update;
DROP TRIGGER native_request_purge_no_delete;
DROP INDEX native_request_purge_receipt_idx;
ALTER TABLE native_request_purge_terminal RENAME TO native_request_purge_terminal_v1_old;
CREATE TABLE native_request_purge_terminal (
    family TEXT NOT NULL CHECK(family IN ('knowledge_update_batch_v1','skill_draft_v1','s05_s08_quota_v1','s05_s08_quota_reset_v1','m5_quota_window_v1','s05_reserve_terminal_v1')),
    account_sha256 TEXT NOT NULL CHECK(length(account_sha256)=64 AND account_sha256 NOT GLOB '*[^0-9a-f]*'),
    request_sha256 TEXT NOT NULL CHECK(length(request_sha256)=64 AND request_sha256 NOT GLOB '*[^0-9a-f]*'),
    body_sha256 TEXT CHECK(body_sha256 IS NULL OR (length(body_sha256)=64 AND body_sha256 NOT GLOB '*[^0-9a-f]*')),
    purge_receipt_id TEXT NOT NULL,
    purge_context_id TEXT NOT NULL,
    effective_at_ms INTEGER,
    CHECK((family IN ('s05_s08_quota_v1','s05_s08_quota_reset_v1','m5_quota_window_v1') AND effective_at_ms IS NOT NULL AND effective_at_ms>=0) OR (family IN ('knowledge_update_batch_v1','skill_draft_v1','s05_reserve_terminal_v1') AND effective_at_ms IS NULL)),
    PRIMARY KEY(family,account_sha256,request_sha256),
    FOREIGN KEY(purge_receipt_id) REFERENCES fm_meta(key) DEFERRABLE INITIALLY DEFERRED
) WITHOUT ROWID;
INSERT INTO native_request_purge_terminal(family,account_sha256,request_sha256,body_sha256,purge_receipt_id,purge_context_id) SELECT family,account_sha256,request_sha256,body_sha256,purge_receipt_id,purge_context_id FROM native_request_purge_terminal_v1_old;
DROP TABLE native_request_purge_terminal_v1_old;
CREATE INDEX native_request_purge_receipt_idx ON native_request_purge_terminal(purge_receipt_id,family);
CREATE TRIGGER native_request_purge_insert_guard BEFORE INSERT ON native_request_purge_terminal
WHEN NOT EXISTS(SELECT 1 FROM fm_v2_privacy_erasure_context c WHERE c.erasure_id=NEW.purge_context_id AND c.source_id IS NULL AND c.authorized_by=c.owner_id AND ((NEW.family='s05_s08_quota_reset_v1' AND c.reason='s05 guarded reset quota terminal') OR (NEW.family='m5_quota_window_v1' AND c.reason='s05 guarded m5 quota terminal') OR (NEW.family='s05_reserve_terminal_v1' AND c.reason IN ('s05 guarded reset quota terminal','native request guarded owner purge terminal')) OR (NEW.family NOT IN ('s05_s08_quota_reset_v1','m5_quota_window_v1','s05_reserve_terminal_v1') AND c.reason='native request guarded owner purge terminal')))
BEGIN SELECT RAISE(ABORT,'request terminal requires guarded owner purge'); END;
CREATE TRIGGER native_request_purge_no_update BEFORE UPDATE ON native_request_purge_terminal BEGIN SELECT RAISE(ABORT,'request terminals are append-only'); END;
CREATE TRIGGER native_request_purge_no_delete BEFORE DELETE ON native_request_purge_terminal BEGIN SELECT RAISE(ABORT,'request terminals are append-only'); END;

CREATE INDEX s05_quota_window_v1 ON fm_v2_s05_reservations(owner_id,COALESCE(settled_at_ms,reserved_at_ms),state);
CREATE INDEX s05_quota_terminal_window_v1 ON native_request_purge_terminal(family,account_sha256,effective_at_ms) WHERE effective_at_ms IS NOT NULL;

-- The offline cutoff is immutable; it does not authorize account access.
CREATE TRIGGER s05_quota_cutoff_no_update BEFORE UPDATE ON fm_meta WHEN OLD.key IN ('openclank.s05.quota_cutoff.v1','openclank.s05.quota_purge.v1') OR NEW.key IN ('openclank.s05.quota_cutoff.v1','openclank.s05.quota_purge.v1') OR OLD.key GLOB 's05_quota_batch_*' OR NEW.key GLOB 's05_quota_batch_*' OR OLD.key GLOB 's05_quota_*_receipt_*' OR NEW.key GLOB 's05_quota_*_receipt_*' OR OLD.key GLOB 's05_quota_slot_terminal_*' OR NEW.key GLOB 's05_quota_slot_terminal_*' BEGIN SELECT RAISE(ABORT,'quota profile is immutable'); END;
CREATE TRIGGER s05_quota_cutoff_no_delete BEFORE DELETE ON fm_meta WHEN (OLD.key IN ('openclank.s05.quota_cutoff.v1','openclank.s05.quota_purge.v1') OR OLD.key GLOB 's05_quota_batch_*' OR OLD.key GLOB 's05_quota_*_receipt_*' OR OLD.key GLOB 's05_quota_slot_terminal_*') BEGIN SELECT RAISE(ABORT,'quota profile is immutable'); END;
CREATE TRIGGER s05_quota_cutoff_no_replace BEFORE INSERT ON fm_meta WHEN (NEW.key IN ('openclank.s05.quota_cutoff.v1','openclank.s05.quota_purge.v1') OR NEW.key GLOB 's05_quota_batch_*' OR NEW.key GLOB 's05_quota_*_receipt_*' OR NEW.key GLOB 's05_quota_slot_terminal_*') AND EXISTS(SELECT 1 FROM fm_meta WHERE key=NEW.key) BEGIN SELECT RAISE(ABORT,'quota profile is immutable'); END;

-- Headers and batches may be created only under the matching indexed lifecycle context.
CREATE TRIGGER s05_quota_header_insert_guard BEFORE INSERT ON fm_meta WHEN NEW.key GLOB 's05_quota_*_receipt_*' AND CASE WHEN json_valid(NEW.value) THEN CASE WHEN json_type(NEW.value,'$.version')='integer' AND json_extract(NEW.value,'$.version')=1 AND json_type(NEW.value,'$.window_account_sha256')='text' AND length(json_extract(NEW.value,'$.window_account_sha256'))=64 AND json_extract(NEW.value,'$.window_account_sha256') NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.value,'$.max_at_ms')='integer' AND json_type(NEW.value,'$.count')='integer' AND json_extract(NEW.value,'$.count') BETWEEN 0 AND 100000 AND json_type(NEW.value,'$.batch_sha256')='array' AND json_array_length(NEW.value,'$.batch_sha256')=(json_extract(NEW.value,'$.count')+63)/64 AND json_type(NEW.value,'$.batch_max_at_ms')='array' AND json_array_length(NEW.value,'$.batch_max_at_ms')=json_array_length(NEW.value,'$.batch_sha256') AND json_type(NEW.value,'$.slot_count')='integer' AND json_extract(NEW.value,'$.slot_count') BETWEEN 0 AND 100000 AND json_type(NEW.value,'$.slot_batch_sha256')='array' AND json_array_length(NEW.value,'$.slot_batch_sha256')=(json_extract(NEW.value,'$.slot_count')+63)/64 AND ((json_extract(NEW.value,'$.count')=0 AND json_extract(NEW.value,'$.max_at_ms')=0) OR (json_extract(NEW.value,'$.count')>0 AND json_extract(NEW.value,'$.max_at_ms')>=0)) AND EXISTS(SELECT 1 FROM native_request_purge_terminal t JOIN fm_v2_privacy_erasure_context c ON c.erasure_id=t.purge_context_id WHERE t.purge_receipt_id=NEW.key AND t.effective_at_ms=json_extract(NEW.value,'$.max_at_ms') AND t.family IN ('s05_s08_quota_reset_v1','s05_s08_quota_v1','m5_quota_window_v1') AND c.source_id IS NULL AND c.authorized_by=c.owner_id AND c.reason IN ('s05 guarded reset quota terminal','native request guarded owner purge terminal','s05 guarded m5 quota terminal')) THEN 0 ELSE 1 END ELSE 1 END BEGIN SELECT RAISE(ABORT,'quota header requires guarded lifecycle'); END;
CREATE TRIGGER s05_quota_batch_insert_guard BEFORE INSERT ON fm_meta WHEN NEW.key GLOB 's05_quota_batch_*' AND CASE WHEN json_valid(NEW.value) THEN CASE WHEN json_type(NEW.value,'$.version')='integer' AND json_extract(NEW.value,'$.version')=1 AND json_type(NEW.value,'$.window_account_sha256')='text' AND length(json_extract(NEW.value,'$.window_account_sha256'))=64 AND json_extract(NEW.value,'$.window_account_sha256') NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.value,'$.max_at_ms')='integer' AND json_extract(NEW.value,'$.max_at_ms')>=0 AND json_type(NEW.value,'$.ordinal')='integer' AND json_extract(NEW.value,'$.ordinal')>=0 AND json_type(NEW.value,'$.entries')='array' AND json_array_length(NEW.value,'$.entries') BETWEEN 1 AND 64 AND EXISTS(SELECT 1 FROM native_request_purge_terminal t JOIN native_request_purge_terminal h ON h.family=t.family AND h.account_sha256=t.account_sha256 AND h.purge_context_id=t.purge_context_id JOIN fm_v2_privacy_erasure_context c ON c.erasure_id=t.purge_context_id WHERE t.purge_receipt_id=NEW.key AND t.effective_at_ms=json_extract(NEW.value,'$.max_at_ms') AND h.purge_receipt_id=json_extract(NEW.value,'$.coverage_receipt_id') AND t.family IN ('s05_s08_quota_reset_v1','s05_s08_quota_v1','m5_quota_window_v1') AND c.source_id IS NULL AND c.authorized_by=c.owner_id AND c.reason IN ('s05 guarded reset quota terminal','native request guarded owner purge terminal','s05 guarded m5 quota terminal')) THEN 0 ELSE 1 END ELSE 1 END BEGIN SELECT RAISE(ABORT,'quota batch requires guarded lifecycle'); END;

CREATE TRIGGER s05_quota_slot_insert_guard BEFORE INSERT ON fm_meta WHEN NEW.key GLOB 's05_quota_slot_terminal_*' AND CASE WHEN json_valid(NEW.value) THEN CASE WHEN json_type(NEW.value,'$.version')='integer' AND json_extract(NEW.value,'$.version')=1 AND json_type(NEW.value,'$.account_id')='text' AND length(json_extract(NEW.value,'$.account_id')) BETWEEN 1 AND 512 AND json_type(NEW.value,'$.captured_owner')='text' AND length(json_extract(NEW.value,'$.captured_owner')) BETWEEN 1 AND 512 AND json_type(NEW.value,'$.workspace_id')='text' AND length(json_extract(NEW.value,'$.workspace_id')) BETWEEN 1 AND 512 AND json_type(NEW.value,'$.slot')='text' AND length(json_extract(NEW.value,'$.slot'))=75 AND substr(json_extract(NEW.value,'$.slot'),1,11)='s05reserve_' AND substr(json_extract(NEW.value,'$.slot'),12) NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.value,'$.original_receipt_sha256')='text' AND length(json_extract(NEW.value,'$.original_receipt_sha256'))=64 AND json_extract(NEW.value,'$.original_receipt_sha256') NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.value,'$.coverage_receipt_id')='text' AND json_type(NEW.value,'$.slot_batch_ordinal')='integer' AND json_extract(NEW.value,'$.slot_batch_ordinal')>=0 AND ((json_extract(NEW.value,'$.disposition') IN ('settled','revoked') AND json_type(NEW.value,'$.result_receipt_sha256')='text' AND length(json_extract(NEW.value,'$.result_receipt_sha256'))=64 AND json_extract(NEW.value,'$.result_receipt_sha256') NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.value,'$.attempt_sha256')='text' AND length(json_extract(NEW.value,'$.attempt_sha256'))=64 AND json_extract(NEW.value,'$.attempt_sha256') NOT GLOB '*[^0-9a-f]*' AND json_type(NEW.value,'$.lease_epoch')='integer' AND json_extract(NEW.value,'$.lease_epoch')>0) OR (json_extract(NEW.value,'$.disposition')='cancelled_before_reserve' AND json_type(NEW.value,'$.result_receipt_sha256')='null' AND json_type(NEW.value,'$.attempt_sha256')='null' AND json_type(NEW.value,'$.lease_epoch')='null')) AND EXISTS(SELECT 1 FROM native_request_purge_terminal t JOIN fm_v2_privacy_erasure_context c ON c.erasure_id=t.purge_context_id JOIN fm_meta h ON h.key=json_extract(NEW.value,'$.coverage_receipt_id') WHERE t.purge_receipt_id=NEW.key AND t.family='s05_reserve_terminal_v1' AND c.source_id IS NULL AND c.authorized_by=c.owner_id AND c.reason IN ('s05 guarded reset quota terminal','native request guarded owner purge terminal') AND json_valid(h.value) AND json_extract(h.value,'$.account_id')=json_extract(NEW.value,'$.account_id')) THEN 0 ELSE 1 END ELSE 1 END BEGIN SELECT RAISE(ABORT,'quota slot terminal requires guarded lifecycle'); END;
